import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;

public class CheckboxSummaryPanel extends JPanel {

    private final JCheckBox opt1 = new JCheckBox("Cheese");
    private final JCheckBox opt2 = new JCheckBox("Pepperoni");
    private final JCheckBox opt3 = new JCheckBox("Olives");
    private final JLabel summary = new JLabel("none");

    public CheckboxSummaryPanel() {
        opt1.setName("opt1");
        opt2.setName("opt2");
        opt3.setName("opt3");
        summary.setName("summary");
        add(opt1);
        add(opt2);
        add(opt3);
        add(summary);
        opt1.addItemListener(e -> updateSummary());
        opt2.addItemListener(e -> updateSummary());
        opt3.addItemListener(e -> updateSummary());
    }

    private void updateSummary() {
        java.util.List<String> selected = new java.util.ArrayList<>();
        for (JCheckBox box : new JCheckBox[] { opt1, opt2, opt3 }) {
            if (box.isSelected()) {
                selected.add(box.getText());
            }
        }
        summary.setText(selected.isEmpty() ? "none" : String.join(", ", selected));
    }
}
